import ast

def insert_fa_briefs():
    # We will use regex to carefully insert 'ai_brief_fa': '...', right after 'ai_brief': '...',
    global content
    for task_id, brief in fa_briefs.items():
        # Find the ai_brief for this task
        # Since string matching can be tricky with multiline, we'll look for ai_brief definition block.
        # But wait, it's easier to just match " 'ai_brief': '...'," and insert it.
        # Let's use re to replace.
        # We need to find the specific block for id: task_id.
        pattern = r"({'id': " + str(task_id) + r",.*?)(  'ai_brief': '.*?',\n)"
        
        # Replacement string, escaping quotes in the persian brief
        brief_escaped = brief.replace("'", "\\'")
        replacement = r"\1\2  'ai_brief_fa': '" + brief_escaped + r"',\n"
        
        content = re.sub(pattern, replacement, content, flags=re.DOTALL)

insert_fa_briefs()

with open(r'd:\My work\workshop\prompt-engineering-workshop\curriculum.py', 'w', encoding='utf-8') as f:
    f.write(content)
print("Done")
